render:
const p = ctx.params;
const w = ctx.width;
const h = ctx.height;
const root = ctx.root;

let effectiveFps = 60;
if (p.step_framerate === '24 FPS') effectiveFps = 24;
else if (p.step_framerate === '18 FPS') effectiveFps = 18;
else if (p.step_framerate === '12 FPS') effectiveFps = 12;

const totalFrames = Math.round(ctx.duration * 60);
const currentFrame = ctx.frame;
const effectiveFrameIndex = Math.floor(ctx.time * effectiveFps);
const discreteTime = effectiveFrameIndex / effectiveFps;

const container = root.querySelector('#mgt-film-container');
const titleWrapper = root.querySelector('#mgt-title-wrapper');
const titleEl = root.querySelector('#mgt-title');
const subtitleEl = root.querySelector('#mgt-subtitle');
const vignetteEl = root.querySelector('#mgt-vignette');
const leaderLayer = root.querySelector('#mgt-leader-layer');
const leaderCircle = root.querySelector('#mgt-leader-circle');
const leaderText = root.querySelector('#mgt-leader-text');
const canvas = root.querySelector('#mgt-film-canvas');
canvas.width = w;
canvas.height = h;
const g = canvas.getContext('2d');

root.style.backgroundColor = p.bg_color;

const inst = p.instability / 100;

function noise(idx) {
  return ctx.random(Math.abs((effectiveFrameIndex * 17 + idx * 1013) % 99991));
}

const weaveMult = (p.gate_weave / 100) * (0.5 + inst * 1.5);
const dx = (noise(1) - 0.5) * 8 * weaveMult;
const dy = (noise(2) - 0.5) * 8 * weaveMult;
const rot = (noise(3) - 0.5) * 0.8 * weaveMult;

let jitterY = 0;
if (noise(4) > (0.93 - inst * 0.15)) {
  jitterY = (noise(5) - 0.5) * 24 * weaveMult;
}

const flickerMult = (p.flicker_amount / 100) * (0.4 + inst * 1.1);
const flickerOpacity = 1 - (noise(6) * 0.25 * flickerMult);
const colorBrightness = 1 + (noise(7) - 0.5) * 0.3 * flickerMult;

const focusMult = (p.focus_breathing / 100) * (0.5 + inst * 1.5);
let blurPx = 0;
if (noise(8) > 0.6) {
  blurPx = noise(9) * 2.2 * focusMult;
}

const chroma = (p.chromatic_aberration / 100) * (1 + inst * 2);
const halation = p.halation_intensity / 100;

titleEl.textContent = p.text_content;
subtitleEl.textContent = p.subtitle_content;
titleEl.style.fontFamily = p.font_family;
titleEl.style.fontSize = p.text_size + 'px';
subtitleEl.style.fontFamily = p.font_family;
subtitleEl.style.fontSize = Math.max(14, Math.round(p.text_size * 0.28)) + 'px';
titleEl.style.color = p.text_color;
subtitleEl.style.color = p.text_color;

titleWrapper.style.left = p.pos_x + '%';
titleWrapper.style.top = p.pos_y + '%';

let textTransform = `translate(-50%, -50%) translate(${dx}px, ${dy + jitterY}px) rotate(${rot}deg)`;
let textFilter = `blur(${blurPx}px) brightness(${colorBrightness})`;

if (halation > 0) {
  const hGlow = Math.round(12 * halation);
  textFilter += ` drop-shadow(0px 0px ${hGlow}px ${p.text_color})`;
}

if (chroma > 0.1) {
  const cOff = (1.5 * chroma).toFixed(1);
  titleEl.style.textShadow = `${cOff}px 0 rgba(255,0,0,0.7), -${cOff}px 0 rgba(0,255,255,0.7)`;
} else {
  titleEl.style.textShadow = 'none';
}

titleWrapper.style.transform = textTransform;
titleWrapper.style.filter = textFilter;
titleWrapper.style.opacity = flickerOpacity;

const leaderDur = p.leader_duration;
const inLeader = ctx.time < leaderDur;

if (inLeader) {
  const leaderProgress = ctx.time / Math.max(0.001, leaderDur);
  const countNum = Math.ceil((1 - leaderProgress) * 8);

  if (p.show_leader_marks) {
    leaderLayer.style.display = 'flex';
    leaderLayer.style.color = p.text_color;
    leaderCircle.style.display = 'block';
    leaderText.style.display = 'block';
    leaderText.textContent = countNum > 0 ? countNum : 'START';
    leaderCircle.style.transform = `scale(${1 + (noise(10) - 0.5) * 0.1})`;
  } else {
    leaderLayer.style.display = 'none';
  }

  if (noise(11) > 0.3) {
    titleWrapper.style.opacity = (noise(12) * 0.5).toString();
    titleWrapper.style.transform = `${textTransform} scaleY(${0.2 + noise(13) * 1.5}) skewX(${(noise(14)-0.5)*40}deg)`;
  }
} else {
  leaderLayer.style.display = 'none';
  if (ctx.editingStop === 'stop_title') {
    titleWrapper.style.opacity = '1';
  }
}

const vigBreath = (p.vignette_breath / 100) * (0.8 + inst * 0.6);
const vigSize = 60 + (noise(15) - 0.5) * 12 * vigBreath;
const vigOpacity = 0.75 + (noise(16) - 0.5) * 0.2 * vigBreath;
vignetteEl.style.background = `radial-gradient(circle, transparent ${vigSize}%, rgba(0,0,0,${vigOpacity}) 100%)`;

g.clearRect(0, 0, w, h);

const grainAmount = Math.floor(1800 * (0.5 + inst));
g.fillStyle = 'rgba(255, 255, 255, 0.08)';
for (let i = 0; i < grainAmount; i++) {
  const gx = noise(i + 20) * w;
  const gy = noise(i + 5000) * h;
  const gsz = noise(i + 10000) > 0.8 ? 2 : 1;
  g.fillRect(gx, gy, gsz, gsz);
}

const dustMult = p.dust_scratch / 100;
if (dustMult > 0) {
  const numSpecks = Math.floor((3 + inst * 12) * dustMult);
  g.fillStyle = noise(101) > 0.3 ? 'rgba(10, 10, 10, 0.75)' : 'rgba(240, 230, 210, 0.7)';

  for (let i = 0; i < numSpecks; i++) {
    const px = noise(i + 200) * w;
    const py = noise(i + 300) * h;
    const pr = 1.5 + noise(i + 400) * 3.5 * (1 + inst);

    g.beginPath();
    g.arc(px, py, pr, 0, Math.PI * 2);
    g.fill();

    if (noise(i + 500) > (0.75 - inst * 0.25)) {
      g.strokeStyle = g.fillStyle;
      g.lineWidth = 1 + noise(i + 600);
      g.beginPath();
      g.moveTo(px, py);
      g.quadraticCurveTo(
        px + (noise(i + 700) - 0.5) * 40,
        py + (noise(i + 800) - 0.5) * 40,
        px + (noise(i + 900) - 0.5) * 70,
        py + (noise(i + 1000) - 0.5) * 70
      );
      g.stroke();
    }
  }

  if (noise(88) < (0.35 + inst * 0.4)) {
    const rx = noise(89) * w;
    const rAlpha = 0.12 + noise(90) * 0.25 * dustMult;
    g.strokeStyle = noise(91) > 0.4 ? `rgba(255, 255, 255, ${rAlpha})` : `rgba(0, 0, 0, ${rAlpha})`;
    g.lineWidth = 1 + noise(92) * 1.5;
    g.beginPath();
    g.moveTo(rx + (noise(93) - 0.5) * 5, 0);
    g.lineTo(rx + (noise(94) - 0.5) * 5, h);
    g.stroke();
  }
}
